// Planche de contrôle : humeurs, maquillage festival, patchs + texte, poses, néon, aura, couleurs libres.
const { chromium } = require('playwright');
const OUT = process.argv[2] || '/tmp/avfun';
(async () => { const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 1400, height: 900 }, deviceScaleFactor: 1 }); const errs = []; p.on('pageerror', e => errs.push(e.message));
  await p.goto('http://127.0.0.1:8090/local.html?nouveau'); await p.waitForTimeout(800);
  const sheet = async (name, items, bg = '#E9ECF5') => { await p.evaluate(([items, bg]) => { document.querySelector('#avq')?.remove(); const d = document.createElement('div'); d.id = 'avq'; d.style.cssText = `position:fixed;inset:0;z-index:99999;background:${bg};display:flex;flex-wrap:wrap;gap:6px;padding:8px;align-content:flex-start;overflow:hidden`;
      items.forEach(([lab, cfg, view, h]) => { const c = document.createElement('div'); c.style.cssText = `background:${bg === '#E9ECF5' ? '#fff' : 'rgba(255,255,255,.06)'};color:${bg === '#E9ECF5' ? '#111' : '#fff'};border-radius:12px;padding:4px;display:flex;flex-direction:column;align-items:center;font:600 11px sans-serif`; c.innerHTML = `<img src="${av2URI(cfg, view || 'full')}" style="height:${h || 240}px;max-width:210px"><span>${lab}</span>`; d.append(c); }); document.body.append(d); }, [items, bg]); await p.waitForTimeout(800); await p.screenshot({ path: `${OUT}_${name}.png` }); };
  const AV2 = await p.evaluate(() => ({ mood: AV2.mood, paint: AV2.paint }));
  const F = { g: 'f', skin: 2, hair: 'waves', hairC: 3 }, M = { g: 'm', skin: 6, hair: 'twists', hairC: 0, beard: 'short' };
  await sheet('humeurs', AV2.mood.flatMap(([k, n]) => [[n, { ...F, mood: k }, 'head', 160], [n, { ...M, mood: k }, 'head', 160]]));
  await sheet('maquillage', AV2.paint.flatMap(([k, n], i) => [[n, { ...F, paint: k, paintC: i % 8 }, 'head', 170], [n + ' (#00E5FF)', { ...M, paint: k, paintC: '#00E5FF' }, 'head', 170]]));
  await sheet('patchs', [['TEAM LÉA', { ...F, top: 'tee', topC: 3, text: 'TEAM LÉA', patches: ['bolt', 'heart'] }], ['BAL DES FOUS 26', { ...M, top: 'hoodie', topC: 0, text: 'BAL DES FOUS 26', patches: ['star', 'flame', 'peace'] }], ['YOLO', { ...F, top: 'crop', topC: '#FF4FD8', text: 'YOLO', patches: ['smile'] }], ['Paris ❤', { ...M, top: 'oversize', topC: '#7CFF6B', text: 'Paris ❤' }], ['polo', { ...M, top: 'polo', topC: 1, text: 'DJ', patches: ['bolt'] }], ['suit (pas de texte)', { ...M, outfit: 'suit', outfitC: 3, text: 'NON', patches: ['heart'] }]].map(([l, c]) => [l, c, 'torso', 230]));
  await sheet('poses', [['danse F', { ...F, pose: 'dance', mood: 'laugh', jewel: ['glowstick', 'bracelets'], glasses: 'led' }], ['danse H', { ...M, pose: 'dance', mood: 'wow', jewel: ['glowstick'], top: 'hoodie' }], ['danse costume', { g: 'm', outfit: 'suit', outfitC: 1, pose: 'dance', mood: 'laugh' }], ['salut + bâton', { ...F, pose: 'wave', jewel: ['glowstick'], mood: 'wink' }], ['dort', { ...M, mood: 'sleep', top: 'hoodie', pose: 'relax' }], ['bâille', { ...F, mood: 'yawn', pose: 'relax' }], ['couleurs libres', { ...F, topC: '#00C2A8', bottomC: '#FF5A8A', shoesC: '#FFE14D', hairC: '#7B61FF', top: 'tee', bottom: 'flare' }]].map(([l, c]) => [l, c, 'full', 330]));
  await sheet('fx', [['néon', { ...F, _fx: 'neon', pose: 'dance', glasses: 'led', jewel: ['glowstick'] }], ['néon H', { ...M, _fx: 'neon', glowC: 0 }], ['aura (ami proche)', { ...F, _fx: 'glow', mood: 'love' }], ['néon + aura', { ...M, _fx: 'neon glow', pose: 'wave', mood: 'laugh' }]].map(([l, c]) => [l, c, 'full', 360]), '#0B0D17');
  console.log('erreurs', errs); await b.close(); })();
